import os, json, glob, re

# Load all grids from the current session
def load_grids():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        session_dir = os.getcwd()

    jsonl_path = os.path.join(session_dir, '../../sessions' + os.path.basename(session_dir) + '.jsonl')
    full_path = os.path.normpath(jsonl_path)

    try:
        if os.path.exists(full_path):
            content = open(full_path).read()
            return content
    except:
        pass
    return None

content = load_grids()
print("Session content loaded:", content[:200] if content else "None/Empty")

# Check for demo pairs and test input
for match in re.finditer(r'(Demo pair (\d+) (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content or ''):
    print(f"Found: {match.group(1)} at {match.group(2)}x{match.group(3)}")

